package com.itsm.changemanagement.controller;
import com.itsm.changemanagement.entity.ConfigRecord;import com.itsm.changemanagement.repository.ConfigRecordRepository;import com.itsm.changemanagement.exception.ApiExceptions;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import java.util.*;

/**
 * REST controller managing customizable ITSM configurations, custom fields, forms, and CAB definitions.
 *
 * <p><b>Purpose:</b> Provides generic CRUD and activation endpoints for customizable resources:
 * {@code custom-fields}, {@code custom-forms}, {@code custom-workflows}, {@code approval-rules},
 * {@code change-categories}, {@code notifications}, {@code cab-meetings}, {@code cab-members},
 * {@code cab-agenda}, and {@code cab-decisions}.
 *
 * <p><b>Downstream / Workflow:</b> Intercepts {@code /api/{kind}/**} requests and manipulates {@link ConfigRecord} entities
 * in the database.
 */
@RestController public class CustomizationController {private final ConfigRecordRepository repo;private final ObjectMapper mapper;public CustomizationController(ConfigRecordRepository r,ObjectMapper m){repo=r;mapper=m;}
 private String json(Object o){try{return mapper.writeValueAsString(o);}catch(Exception e){throw new IllegalArgumentException("Invalid JSON payload");}}private Map<String,Object> view(ConfigRecord r){try{Map<String,Object> m=mapper.readValue(r.getPayload(),Map.class);m.put("id",r.getId());m.put("key",r.getConfigKey());m.put("active",r.isActive());m.put("createdAt",r.getCreatedAt());m.put("updatedAt",r.getUpdatedAt());return m;}catch(Exception e){return Map.of("id",r.getId(),"payload",r.getPayload());}}
 @PostMapping("/api/{kind}")@Transactional public ResponseEntity<?> create(@PathVariable String kind,@RequestBody Map<String,Object> body){String type=normalize(kind);String key=String.valueOf(body.getOrDefault("key",body.getOrDefault("fieldKey",body.getOrDefault("name",UUID.randomUUID().toString()))));if(repo.findByConfigTypeAndConfigKey(type,key).isPresent())throw new ApiExceptions.Conflict("Configuration key already exists: "+key);validate(type,body);ConfigRecord saved=repo.save(new ConfigRecord(type,key,json(body)));return ResponseEntity.status(201).body(view(saved));}
 @GetMapping("/api/{kind}")public List<Map<String,Object>> list(@PathVariable String kind,@RequestParam(required=false)Boolean active){String type=normalize(kind);return (active==null?repo.findByConfigType(type):active?repo.findByConfigTypeAndActiveTrue(type):repo.findByConfigType(type).stream().filter(x->!x.isActive()).toList()).stream().map(this::view).toList();}
 @GetMapping("/api/{kind}/{id}")public Map<String,Object> get(@PathVariable String kind,@PathVariable Long id){return view(find(normalize(kind),id));}
 @PutMapping("/api/{kind}/{id}")@Transactional public Map<String,Object> update(@PathVariable String kind,@PathVariable Long id,@RequestBody Map<String,Object> body){ConfigRecord r=find(normalize(kind),id);validate(r.getConfigType(),body);r.setPayload(json(body));return view(repo.save(r));}
 @DeleteMapping("/api/{kind}/{id}")@Transactional public ResponseEntity<?> delete(@PathVariable String kind,@PathVariable Long id){ConfigRecord r=find(normalize(kind),id);if("custom-fields".equals(r.getConfigType())){r.setActive(false);repo.save(r);}else repo.delete(r);return ResponseEntity.noContent().build();}
 @GetMapping("/api/custom-fields/active")public List<Map<String,Object>> activeFields(){return repo.findByConfigTypeAndActiveTrue("custom-fields").stream().map(this::view).toList();}
 @GetMapping("/api/custom-forms/{id}/preview")public Map<String,Object> preview(@PathVariable Long id){Map<String,Object> f=view(find("custom-forms",id));return Map.of("form",f,"previewOnly",true,"note","The form definition is persisted; clients render the returned field/section configuration.");}
 @PostMapping("/api/custom-workflows/{id}/activate")public Map<String,Object> activateWorkflow(@PathVariable Long id){return active("custom-workflows",id,true);}@PostMapping("/api/custom-workflows/{id}/deactivate")public Map<String,Object> deactivateWorkflow(@PathVariable Long id){return active("custom-workflows",id,false);}@PostMapping("/api/approval-rules/{id}/activate")public Map<String,Object> activateRule(@PathVariable Long id){return active("approval-rules",id,true);}
 @PostMapping("/api/cab/meetings")public ResponseEntity<?> meeting(@RequestBody Map<String,Object>b){return create("cab-meetings",b);}@GetMapping("/api/cab/meetings")public List<Map<String,Object>> meetings(){return list("cab-meetings",null);}@PostMapping("/api/cab/meetings/{meetingId}/members")public ResponseEntity<?> member(@PathVariable Long meetingId,@RequestBody Map<String,Object>b){find("cab-meetings",meetingId);b.put("meetingId",meetingId);return create("cab-members",b);}@PostMapping("/api/cab/meetings/{meetingId}/changes/{changeId}")public ResponseEntity<?> addChange(@PathVariable Long meetingId,@PathVariable Long changeId,@RequestBody(required=false)Map<String,Object>b){find("cab-meetings",meetingId);Map<String,Object>x=b==null?new HashMap<>():new HashMap<>(b);x.put("meetingId",meetingId);x.put("changeId",changeId);return create("cab-agenda",x);}@PostMapping("/api/cab/meetings/{meetingId}/changes/{changeId}/decision")public ResponseEntity<?> decision(@PathVariable Long meetingId,@PathVariable Long changeId,@RequestBody Map<String,Object>b){find("cab-meetings",meetingId);b.put("meetingId",meetingId);b.put("changeId",changeId);b.put("decisionDate",java.time.Instant.now().toString());return create("cab-decisions",b);}
 private Map<String,Object> active(String type,Long id,boolean a){ConfigRecord r=find(type,id);r.setActive(a);return view(repo.save(r));}private ConfigRecord find(String type,Long id){ConfigRecord r=repo.findById(id).orElseThrow(()->new ApiExceptions.NotFound("Configuration not found: "+id));if(!r.getConfigType().equals(type))throw new ApiExceptions.NotFound("Configuration not found for type "+type);return r;}
 private String normalize(String k){return switch(k){case "custom-fields","custom-forms","custom-workflows","approval-rules","change-categories","notifications","cab-meetings","cab-members","cab-agenda","cab-decisions"->k;default->throw new ApiExceptions.NotFound("Unknown configuration resource: "+k);};}
 private void validate(String type,Map<String,Object>b){if("custom-fields".equals(type)){for(String k:List.of("fieldLabel","fieldKey","fieldType"))if(b.get(k)==null||String.valueOf(b.get(k)).isBlank())throw new ApiExceptions.Invalid(k+" is required");Set<String> types=Set.of("SINGLE_LINE_TEXT","MULTI_LINE_TEXT","INTEGER","DECIMAL","BOOLEAN","DATE","DATETIME","EMAIL","PHONE","URL","DROPDOWN","MULTI_SELECT","RADIO","REFERENCE","USER_REFERENCE","DEPARTMENT_REFERENCE","CI_REFERENCE","ATTACHMENT");if(!types.contains(String.valueOf(b.get("fieldType")).toUpperCase()))throw new ApiExceptions.Invalid("Unsupported fieldType");if(Boolean.TRUE.equals(b.get("required"))&&b.get("defaultValue")==null&&Boolean.TRUE.equals(b.get("readOnly")))throw new ApiExceptions.Invalid("Required read-only field must have a defaultValue");}if("custom-workflows".equals(type)&&b.get("steps")==null)throw new ApiExceptions.Invalid("Workflow steps are required");if("approval-rules".equals(type)&&b.get("conditions")==null)throw new ApiExceptions.Invalid("Rule conditions are required; use declarative conditions, never executable scripts");}
}
